<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted, type CSSProperties } from 'vue';
import { Renderer, Program, Mesh, Triangle, Color } from 'ogl';

export type ButtonSize = 'sm' | 'md' | 'lg';

interface SpecularButtonProps {
  size?: ButtonSize;
  radius?: number;
  tint?: string;
  tintOpacity?: number;
  blur?: number;
  textColor?: string;
  lineColor?: string;
  baseColor?: string;
  intensity?: number;
  shineSize?: number;
  shineFade?: number;
  thickness?: number;
  speed?: number;
  followMouse?: boolean;
  proximity?: number;
  autoAnimate?: boolean;
  disabled?: boolean;
  type?: 'button' | 'submit' | 'reset';
}

const PAD = 20;

const SIZES: Record<ButtonSize, string> = {
  sm: 'text-[0.85rem] px-[22px] py-[10px]',
  md: 'text-[1rem] px-[30px] py-[14px]',
  lg: 'text-[1.15rem] px-10 py-[18px]',
};

const VERT = `#version 300 es
in vec2 position;
void main() {
  gl_Position = vec4(position, 0.0, 1.0);
}
`;

const FRAG = `#version 300 es
precision highp float;

uniform vec2 uCenter;
uniform vec2 uHalfSize;
uniform float uRadius;
uniform float uAngle;
uniform float uPx;
uniform vec3 uLineColor;
uniform vec3 uBaseColor;
uniform float uIntensity;
uniform float uShineSize;
uniform float uShineFade;
uniform float uThickness;
uniform float uBaseWidth;

out vec4 fragColor;

float sdRoundedRect(vec2 p, vec2 b, float r) {
  vec2 q = abs(p) - b + r;
  return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
}

float shapeSDF(vec2 p) { return sdRoundedRect(p, uHalfSize, uRadius); }

float gaussianLine(float d, float sigma) {
  float x = d / (sigma + 1e-6);
  float k = mix(1.0, 1.6, smoothstep(0.0, 1.5, x));
  return exp(-k * x * x);
}

void main() {
  vec2 p = gl_FragCoord.xy - uCenter;
  float d = shapeSDF(p);
  vec2 L = vec2(cos(uAngle), sin(uAngle));

  float base = (1.0 - smoothstep(0.0, uBaseWidth, abs(d))) * 0.45;

  vec2 nEll = normalize(p / (uHalfSize * uHalfSize) + 1e-6);
  float phi = acos(clamp(abs(dot(nEll, L)), 0.0, 1.0));
  float rim = 1.0 - smoothstep(uShineSize - uShineFade, uShineSize + uShineFade + 1e-4, phi);
  float line = gaussianLine(d, uThickness);
  float edgeClamp = 1.0 - smoothstep(0.5 * uPx, 3.0 * uPx, abs(d));
  float hi = line * rim * edgeClamp * uIntensity;

  vec3 col = uBaseColor * base + uLineColor * hi;
  float a = clamp(base + hi, 0.0, 1.0);
  fragColor = vec4(col, a);
}
`;

const props = withDefaults(defineProps<SpecularButtonProps>(), {
  size: 'lg',
  radius: 18,
  tint: '#ffffff',
  tintOpacity: 0,
  blur: 0,
  textColor: '#f5f5f5',
  lineColor: '#ffffff',
  baseColor: '#525252',
  intensity: 1,
  shineSize: 10,
  shineFade: 40,
  thickness: 1,
  speed: 0.35,
  followMouse: true,
  proximity: 250,
  autoAnimate: false,
  disabled: false,
  type: 'button',
});

const btnRef = ref<HTMLButtonElement | null>(null);
const fxRef = ref<HTMLSpanElement | null>(null);

const sizeClass = computed(() => SIZES[props.size] || SIZES.md);

const buttonStyle = computed<CSSProperties>(() => ({
  '--sb-radius': `${props.radius}px`,
  '--sb-tint': props.tint,
  '--sb-tint-opacity': String(props.tintOpacity),
  '--sb-blur': `${props.blur}px`,
  '--sb-text-color': props.textColor,
}));

// Cleanup refs so onUnmounted can access them without closure issues on HMR
let _cancelRaf: (() => void) | null = null;
let _disconnect: (() => void) | null = null;
let _removePointer: (() => void) | null = null;
let _destroyGl: (() => void) | null = null;

onUnmounted(() => {
  _cancelRaf?.();
  _disconnect?.();
  _removePointer?.();
  _destroyGl?.();
});

onMounted(() => {
  const btn = btnRef.value;
  const fx = fxRef.value;
  if (!btn || !fx) return;

  const dpr = window.devicePixelRatio || 1;
  const renderer = new Renderer({ alpha: true, premultipliedAlpha: true, antialias: true, dpr });
  const gl = renderer.gl;
  gl.clearColor(0, 0, 0, 0);
  gl.enable(gl.BLEND);
  gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);

  const geometry = new Triangle(gl);
  if (geometry.attributes.uv) delete geometry.attributes.uv;

  const program = new Program(gl, {
    vertex: VERT,
    fragment: FRAG,
    uniforms: {
      uCenter:    { value: [0, 0] },
      uHalfSize:  { value: [1, 1] },
      uRadius:    { value: 0 },
      uAngle:     { value: 2.4 },
      uPx:        { value: dpr },
      uLineColor: { value: [1, 1, 1] },
      uBaseColor: { value: [0.32, 0.32, 0.32] },
      uIntensity: { value: 1 },
      uShineSize: { value: 0.17 },
      uShineFade: { value: 0.7 },
      uThickness: { value: 1 },
      uBaseWidth: { value: dpr },
    },
  });

  const mesh = new Mesh(gl, { geometry, program });

  // Style the canvas directly in JS — Tailwind v4 does not support [&_canvas] child selectors
  const canvas = gl.canvas as HTMLCanvasElement;
  canvas.style.display = 'block';
  canvas.style.width = '100%';
  canvas.style.height = '100%';
  fx.appendChild(canvas);

  const sizeRef = { w: 1, h: 1 };
  const resize = () => {
    const rect = btn.getBoundingClientRect();
    const w = rect.width;
    const h = rect.height;
    sizeRef.w = w;
    sizeRef.h = h;
    renderer.setSize(w + PAD * 2, h + PAD * 2);
    program.uniforms.uCenter.value  = [(PAD + w / 2) * dpr, (PAD + h / 2) * dpr];
    program.uniforms.uHalfSize.value = [(w / 2) * dpr,      (h / 2) * dpr];
  };
  const ro = new ResizeObserver(resize);
  ro.observe(btn);
  resize();

  let pointerAngle: number | null = null;
  let proximityT = 0;

  const onPointerMove = (e: PointerEvent) => {
    const rect = btn.getBoundingClientRect();
    const cx = rect.left + rect.width  / 2;
    const cy = rect.top  + rect.height / 2;
    const dx = Math.max(rect.left - e.clientX, 0, e.clientX - rect.right);
    const dy = Math.max(rect.top  - e.clientY, 0, e.clientY - rect.bottom);
    const dist = Math.hypot(dx, dy);

    if (dist === 0) {
      const nx = (e.clientX - cx) / (rect.width  / 2);
      const ny = (cy - e.clientY) / (rect.height / 2);
      pointerAngle = Math.atan2(2 / rect.height, -2 / rect.width) + nx * 0.3 + ny * 0.15;
    } else {
      pointerAngle = Math.atan2(cy - e.clientY, e.clientX - cx);
    }

    const t = Math.max(0, 1 - dist / Math.max(props.proximity, 1));
    proximityT = t * t * (3 - 2 * t);
  };

  window.addEventListener('pointermove', onPointerMove);

  let angle     = 2.4;
  let idleAngle = 2.4;
  let bright    = 0;
  let last      = performance.now();
  let raf       = 0;

  const lineC = new Color();
  const baseC = new Color();

  const update = (now: number) => {
    raf = requestAnimationFrame(update);
    const dt = Math.min((now - last) / 1000, 0.05);
    last = now;

    idleAngle += props.speed * dt;
    const steer  = props.followMouse && pointerAngle != null && (!props.autoAnimate || proximityT > 0);
    const target = steer ? pointerAngle! : idleAngle;
    const diff   = ((target - angle + Math.PI * 3) % (Math.PI * 2)) - Math.PI;
    angle += diff * (1 - Math.exp(-dt * 7));

    const brightTarget = props.autoAnimate ? 1 : proximityT;
    bright += (brightTarget - bright) * (1 - Math.exp(-dt * 8));

    lineC.set(props.lineColor);
    baseC.set(props.baseColor);

    program.uniforms.uAngle.value     = angle;
    program.uniforms.uRadius.value    = Math.min(props.radius, Math.min(sizeRef.w, sizeRef.h) / 2) * dpr;
    program.uniforms.uLineColor.value = [lineC.r, lineC.g, lineC.b];
    program.uniforms.uBaseColor.value = [baseC.r, baseC.g, baseC.b];
    program.uniforms.uIntensity.value = props.intensity * bright;
    program.uniforms.uShineSize.value = (props.shineSize * Math.PI) / 180;
    program.uniforms.uShineFade.value = (props.shineFade * Math.PI) / 180;
    program.uniforms.uThickness.value = props.thickness * dpr;

    renderer.render({ scene: mesh });
  };

  raf = requestAnimationFrame(update);

  // Wire up cleanup refs for onUnmounted (registered at setup level)
  _cancelRaf    = () => cancelAnimationFrame(raf);
  _disconnect   = () => ro.disconnect();
  _removePointer = () => window.removeEventListener('pointermove', onPointerMove);
  _destroyGl    = () => {
    if (canvas.parentNode === fx) fx.removeChild(canvas);
    gl.getExtension('WEBGL_lose_context')?.loseContext();
  };
});
</script>

<template>
  <button
    ref="btnRef"
    :type="type"
    :disabled="disabled"
    :class="[
      'relative m-0 inline-flex cursor-pointer items-center justify-center border-none font-medium leading-none tracking-[0.01em] outline-none transition-transform duration-150 active:scale-[0.97] disabled:cursor-default disabled:opacity-55 disabled:active:scale-100',
      'rounded-(--sb-radius)',
      '[background:color-mix(in_srgb,var(--sb-tint)_calc(var(--sb-tint-opacity)*100%),transparent)]',
      '[backdrop-filter:blur(var(--sb-blur))]',
      'shadow-[inset_0_1px_0_rgba(255,255,255,0.04),0_8px_24px_rgba(0,0,0,0.25)]',
      'focus-visible:outline-2 focus-visible:outline-offset-[3px]',
      sizeClass,
    ]"
    :style="[buttonStyle, { color: props.textColor }]"
  >
    <!--
      Canvas overlay: z-index and sizing set via inline style.
      Tailwind v4 does NOT support [&_canvas] child-selector variants.
    -->
    <span
      ref="fxRef"
      aria-hidden="true"
      style="position:absolute; inset:-20px; z-index:1; pointer-events:none;"
    />
    <span style="position:relative; z-index:2;">
      <slot>Get Started</slot>
    </span>
  </button>
</template>
